"""Synthetic market for offline paper runs. Outcomes are generated by this file's own
assumptions - PnL from it says nothing about real-world edge. It exists to exercise the
pipeline end to end."""
import math
import random
from collections import deque
from datetime import datetime
from typing import Dict, List, Optional

from .config import Config
from .models import Pair

SOURCES = ["pump.fun", "raydium", "meteora"]


class _Tok:
    def __init__(self, rng: random.Random, n: int, born: float, cfg: Config):
        r = rng.random()
        self.kind = "dud" if r < .60 else "fade" if r < .82 else "runner" if r < .88 else "rug"
        self.addr = f"SIM{n:05d}" + "".join(rng.choice("abcdefghijkmnpqrstuvwxyz") for _ in range(6))
        self.symbol = "".join(rng.choice("ABCDEFGHJKLMNPRSTUVWXYZ") for _ in range(rng.randint(3, 5)))
        self.source = rng.choices(SOURCES, [.5, .3, .2])[0]
        self.born = born
        self.price0 = self.price = 10 ** rng.uniform(-6, -3)
        self.liq0 = math.exp(rng.gauss(math.log(60_000), .5))
        self.liq = self.liq0
        self.base_vol = self.liq0 * rng.uniform(.04, .12)      # per 5 min, quiet state
        self.holders = rng.randint(150, 700)
        self.hist = deque([self.holders] * 60, maxlen=60)       # 10 min @ 10 s ticks
        self.vol_ema = self.base_vol
        self.high = self.price
        self.hist_price = deque([self.price] * 360, maxlen=360)  # 1 h
        # security profile: some tokens are clean, rugs are sometimes clean-looking
        clean = rng.random() < (.25 if self.kind == "rug" else .45)
        if clean:
            self.dev, self.top10, self.bundled = rng.uniform(.5, 4.5), rng.uniform(12, 33), False
            self.lp, self.frozen, self.mauth, self.honey = rng.choice(["burned", "burned", "locked_30d"]), False, False, False
        else:
            self.dev, self.top10 = rng.uniform(1, 25), rng.uniform(15, 70)
            self.bundled = rng.random() < .4
            self.lp = rng.choice(["burned", "locked_short", "unlocked", "locked_30d"])
            self.frozen, self.mauth = rng.random() < .1, rng.random() < .15
            self.honey = rng.random() < .1
            if not (self.dev >= 5 or self.top10 >= 35 or self.bundled or self.lp in ("unlocked", "locked_short")
                    or self.frozen or self.mauth or self.honey):
                self.dev = 7.0
        # price path plan
        self.t0 = rng.uniform(600, 3 * 3600)          # when the move starts (s after launch)
        self.dur = rng.uniform(600, 2400)
        self.gain = math.log(rng.uniform(2.2, 14)) if self.kind == "runner" else \
            math.log(rng.uniform(1.2, 2.2)) if self.kind == "fade" else 0.0
        self.fake_spike = self.kind in ("dud", "rug") and rng.random() < .5
        self.rug_at = rng.uniform(900, 3 * 3600) if self.kind == "rug" else None
        self.rug_pulls_lp = rng.random() < .5
        self.dev_sold = self.lp_pulled = False
        self.kol = False
        self.smart = 0
        self.buy_ratio = .5
        self.precursor_lead = rng.uniform(120, 300)
        self.kol_roll = rng.random()


class SimFeed:
    def __init__(self, cfg: Config, now: datetime, seed: int = 7, launches_per_min: float = 1.5):
        self.cfg, self.rng, self.n = cfg, random.Random(seed), 0
        self.now, self.t = now, 0.0
        self.rate = launches_per_min
        self.toks: Dict[str, _Tok] = {}
        for _ in range(int(40 * launches_per_min)):          # warm start: pairs of varied age
            self._spawn(-self.rng.uniform(0, 3600 * 4))

    def _spawn(self, born):
        self.n += 1
        t = _Tok(self.rng, self.n, born, self.cfg)
        self.toks[t.addr] = t

    def step(self, now: datetime):
        dt = self.cfg.tick_s
        self.now = now
        self.t += dt
        rng = self.rng
        for _ in range(self._poisson(self.rate * dt / 60)):
            self._spawn(self.t)
        for a in [a for a, k in self.toks.items() if self.t - k.born > 7 * 3600]:
            del self.toks[a]
        for k in self.toks.values():
            self._tick(k, dt, rng)

    def _poisson(self, lam):
        L, k, p = math.exp(-lam), 0, 1.0
        while True:
            p *= self.rng.random()
            if p <= L:
                return k
            k += 1

    def _tick(self, k: _Tok, dt, rng):
        age = self.t - k.born
        ph = age - k.t0
        mu, sigma = 0.0, 0.012
        active = precursor = False
        if k.kind in ("runner", "fade") and 0 <= ph <= k.dur:
            active = True
            mu = k.gain / k.dur * 1.0
            sigma = .02
        elif k.kind in ("runner", "fade") and ph > k.dur:
            mu, sigma = -.00025, .015              # post-move decay
        elif k.kind == "dud":
            mu = -.00002
        if k.kind in ("runner", "fade") and -k.precursor_lead <= ph < 0:
            precursor = True
        if k.fake_spike and 900 < age < 1500:
            precursor = True
        k.price *= math.exp(mu * dt + sigma * math.sqrt(dt / 10) * rng.gauss(0, 1))
        if k.rug_at is not None and age >= k.rug_at and not k.dev_sold:
            k.dev_sold = True
            k.price *= .2
            k.liq *= .3
            k.lp_pulled = k.rug_pulls_lp
        k.liq = max(k.liq0 * math.sqrt(max(k.price / k.price0, .05)), 1) if not k.dev_sold else k.liq
        k.high = max(k.high, k.price)
        k.hist_price.append(k.price)
        # volume / flow
        mult = 1.0
        if precursor:
            mult = 6.5
        elif active:
            mult = 4.0 if k.kind == "runner" else 2.5
        vol = k.base_vol * mult * math.exp(rng.gauss(0, .25))
        k.vol_ema += (vol - k.vol_ema) * dt / 3600
        k.vol5m = vol
        k.buy_ratio = (.76 if (precursor or active) and k.kind == "runner" else
                       .66 if precursor or active else .5) + rng.gauss(0, .04)
        grow = 0.6 if (precursor or active) else 0.05
        k.holders += self._poisson(grow * dt / 10 * (3 if k.kind == "runner" else 1))
        k.hist.append(k.holders)
        if precursor and k.kind == "runner":
            k.smart = max(0, int(rng.gauss(3.2, 1.4)))
            k.kol = k.kol_roll < .4
        elif precursor:
            k.smart = max(0, int(rng.gauss(.8, 1.0)))
            k.kol = k.kol_roll < .05
        else:
            k.smart = 0 if not active else k.smart
        k.vol5m = vol

    def _pair(self, k: _Tok) -> Pair:
        n = max(int(k.vol5m / 160), 1)
        buys = int(n * min(max(k.buy_ratio, .05), .95))
        return Pair(
            addr=k.addr, symbol=k.symbol, source=k.source, age_s=self.t - k.born, price=k.price,
            liquidity=k.liq, vol5m=k.vol5m, vol_avg5m_1h=k.vol_ema, buys5m=buys, sells5m=n - buys,
            holders=k.holders, holders_10m=k.hist[0], price_1h_ago=k.hist_price[0],
            pullback_pct=1 - k.price / k.high if k.high else 0,
            smart_buyers_10m=k.smart, kol_bought=k.kol,
            dev_pct=k.dev, top10_pct=k.top10, bundled=k.bundled, lp_status=k.lp,
            mint_frozen=k.frozen, mint_auth_open=k.mauth, honeypot=k.honey,
            dev_sold=k.dev_sold, lp_pulled=k.lp_pulled)

    def snapshot(self) -> List[Pair]:
        return [self._pair(k) for k in self.toks.values() if self.t - k.born <= self.cfg.max_age_s]

    def get(self, addr: str) -> Optional[Pair]:
        k = self.toks.get(addr)
        return self._pair(k) if k else None
